/**
 * Customer reviews as cards or plain entries: rating, title, text, author and date. Axes: layout (list, grid),
 * columns, item (card, plain), avatar (none, image), tone, density.
 */
import { type ReactNode } from "react";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { ArticleBlock } from "../components/article-block";
import { MediaFrame } from "../components/media-frame";
import { Rating } from "../components/rating";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl } from "../utils";
import type { Review, ReviewLabels } from "./review-list.types";

export type ReviewListProps = {
  id: string;
  title: string;
  reviews: Review[];
  labels: ReviewLabels;
  layout?: "list" | "grid";
  item?: "card" | "plain";
  avatar?: "none" | "image";
  tone?: "default" | "muted";
  density?: "default" | "roomy";
  landmarkLabel?: string;
};

export function ReviewList({
  id,
  title,
  reviews,
  labels,
  layout = "list",
  item = "card",
  avatar = "none",
  tone = "default",
  density = "default",
  landmarkLabel,
}: ReviewListProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      measure={(((layout as string) === "list") ? "2xl" : "default")}
      landmarkLabel={landmarkLabel}
    >
      <Grid cols={(((layout as string) === "grid") ? "1-3" : "1")} className="gap-4" data-testid="items">
        {(reviews ?? []).map((r) => (
          <ArticleBlock key={r.id}
            className={cn(
              "flex h-full flex-col gap-4",
              (
                (item as string) === "card" ? "rounded bg-card p-6 inset-ring inset-ring-border"
                : "border-b border-border pb-4"
              )
            )}
            testid="item"
          >
            <Rating value={r.rating} label={tpl(labels.ratingLabel, r.rating)} />
            <Title as={3} size="base" weight="bold">
              {r.title}
            </Title>
            <Text size="sm" className="text-muted-foreground">
              {r.text}
            </Text>
            <Group gap="4" align="center" className="mt-auto">
              {((avatar as string) === "image") ? (
                <MediaFrame alt={r.author} ratio="1/1" className="size-10 shrink-0 rounded-full" />
              ) : null}
              <Stack gap="0">
                <Text size="sm" weight="semibold">
                  {r.author}
                </Text>
                <Text size="xs" className="text-muted-foreground">
                  {r.date}
                </Text>
              </Stack>
            </Group>
          </ArticleBlock>
        ))}
      </Grid>
    </SectionFrame>
  );
}

